# Bei einer Wiederaufnahme bleiben alte Messwerte erhalten. Zuvor wurden
# metrics.csv und damit der wissenschaftliche Trainingsverlauf ueberschrieben.
_ersetze_trainingsquelle(
    '    with metrics_path.open("w", encoding="utf-8", newline="") as handle:\n'
    '        writer = csv.DictWriter(handle, fieldnames=["step", "train_loss", "valid_loss", "lr", "seconds"])\n'
    '        writer.writeheader()\n',
    '    metrics_vorhanden = metrics_path.exists() and metrics_path.stat().st_size > 0\n'
    '    with metrics_path.open("a" if metrics_vorhanden else "w", encoding="utf-8", newline="") as handle:\n'
    '        writer = csv.DictWriter(handle, fieldnames=["step", "train_loss", "valid_loss", "lr", "seconds"])\n'
    '        if not metrics_vorhanden:\n'
    '            writer.writeheader()\n',
)

# itertools.cycle speichert jeden 30s-Batch im RAM. Ein erneutes Iterieren ueber
# den DataLoader mischt pro Epoche neu und behaelt die Audiodaten nicht im Cache.
_ersetze_trainingsquelle(
    '        train_iter: Iterable[Dict[str, Any]] = itertools.cycle(train_loader)',
    '        def wiederhole_loader(loader: DataLoader) -> Iterable[Dict[str, Any]]:\n'
    '            while True:\n'
    '                yield from loader\n'
    '\n'
    '        train_iter: Iterable[Dict[str, Any]] = wiederhole_loader(train_loader)',
)

COMMANDS = ['train', 'generate', 'review', 'longform', 'human-loop', 'setup-model', 'status', 'lora-status', 'check-audio', 'audio-bewertung', 'bewertungs-analyse', 'export']
# Einige Befehle benoetigen gemeinsame LoRA-Hilfsfunktionen. Diese werden erst
# geladen, wenn ein solcher Befehl wirklich gestartet wird.
DEPENDENCIES = {'train': ['lora_utils'], 'generate': ['lora_utils'], 'review': ['lora_utils'], 'setup-model': ['lora_utils']}

def _load_module(name: str) -> None:
    """Laedt ein eingebettetes Hilfsmodul wie `lora_utils` in den Prozess."""
    if name in sys.modules:
        return
    source = MODULES[name]
    module = types.ModuleType(name)
    module.__file__ = str(Path(__file__).resolve())
    module.__package__ = ""
    sys.modules[name] = module
    exec(compile(source, f"{Path(__file__).name}:{name}", "exec"), module.__dict__)

def _run(command: str, args: list[str]) -> int:
    """Fuehrt einen Training-Unterbefehl isoliert mit eigener Argumentliste aus."""
    if command == "longform":
        old_argv = sys.argv[:]
        sys.argv = [f"{Path(__file__).name} {command}", *args]
        try:
            runpy.run_path(str(Path(__file__).with_name("clips_loopen.py")), run_name="__main__")
        except SystemExit as exc:
            code = exc.code
            return int(code) if isinstance(code, int) else 0
        finally:
            sys.argv = old_argv
        return 0
    if command in {"audio-bewertung", "bewertungs-analyse"}:
        befehl = "audio" if command == "audio-bewertung" else "analyse"
        old_argv = sys.argv[:]
        sys.argv = [f"{Path(__file__).name} {command}", befehl, *args]
        try:
            runpy.run_path(str(Path(__file__).with_name("audio_bewertung.py")), run_name="__main__")
        except SystemExit as exc:
            code = exc.code
            return int(code) if isinstance(code, int) else 0
        finally:
            sys.argv = old_argv
        return 0
    for dep in DEPENDENCIES.get(command, []):
        _load_module(dep)
    old_argv = sys.argv[:]
    sys.argv = [f"{Path(__file__).name} {command}", *args]
    namespace = {
        "__name__": "__main__",
        "__file__": str(Path(__file__).resolve()),
        "__package__": "",
    }
    try:
        exec(compile(MODULES[command], f"{Path(__file__).name}:{command}", "exec"), namespace)
    except SystemExit as exc:
        code = exc.code
        return int(code) if isinstance(code, int) else 0
    finally:
        sys.argv = old_argv
    return 0

def _help() -> None:
    """Zeigt die wichtigsten Training- und Generierungsbefehle."""
    print('Training-Befehle:')
    for name in COMMANDS:
        print(f"  {name}")
    print("\nBeispiele:")
    print('.venv/bin/python code/src/Training/musicgen_steuerung.py train --mode train --auto-vram')
    print('.venv/bin/python code/src/Training/musicgen_steuerung.py review --adapter-path <checkpoint>')
    print('.venv/bin/python code/src/Training/musicgen_steuerung.py longform --dauer 30m')
    print('.venv/bin/python code/src/Training/musicgen_steuerung.py audio-bewertung --audio <audio.mp3>')
    print('.venv/bin/python code/src/Training/musicgen_steuerung.py bewertungs-analyse')

def main() -> int:
    """CLI-Einstiegspunkt fuer LoRA-Training, Review und Longform."""
    if len(sys.argv) < 2 or sys.argv[1] in {"-h", "--help"}:
        _help()
        return 0
    command = sys.argv[1]
    if command not in COMMANDS:
        print(f"Unbekannter Befehl: {command}", file=sys.stderr)
        _help()
        return 2
    return _run(command, sys.argv[2:])

if __name__ == "__main__":
    raise SystemExit(main())
